local _, addon = ...

addon.localeData.enUS.texts = {
 HUNTERS_MARK={ziel={"I have my eye on you, %s.","*fixes %s with a hunter's measured stare.*"},gruppe={"The prey is marked.","*signals the marked target to the companions.*"}},
 ARCANE_SHOT={ziel={"Arcane fire finds you, %s.","*fires at %s as arcane energy flares around the shot.*"},gruppe={"Arcane charge ready. Fire.","*looses a shot shimmering with arcane light.*"}},
 AIMED_SHOT={ziel={"One breath. One target. One shot, %s.","*takes careful aim at %s and holds steady.*"},gruppe={"*holds their breath and takes careful aim.*","I have an angle. Hold still."}},
 MULTI_SHOT={ziel={"One target is not enough today, %s.","*swings the weapon across %s and the surrounding targets.*"},gruppe={"*fires several shots in rapid succession.*","Several targets. Now."}},
 STEADY_SHOT={ziel={"Steady aim. Clean hit, %s.","*takes aim at %s again and holds perfectly still.*"},gruppe={"No haste. Clean shots.","*breathes out slowly and aims again.*"}},
 KILL_COMMAND={ziel={"Now! On %s!","*gives the companion a sharp hand signal toward %s.*"},gruppe={"Go! Now!","*sends the companion forward with a crisp command.*"}},
 MEND_PET={ziel={"Easy, old friend. I've got you.","*kneels beside %s and tends the wounds carefully.*"},gruppe={"Easy. You'll be fine.","*tends the companion's wounds with practiced hands.*"}},
 REVIVE_PET={ziel={"Come back, old friend. The hunt is not over.","*leans close to %s and searches anxiously for a sign of life.*"},gruppe={"Come on. I'm not leaving without you.","*kneels beside the fallen companion and refuses to move away.*"}},
 FEED_PET={ziel={"Here. You earned this.","*offers %s a well-earned portion of food.*"},gruppe={"You get your share. As always.","*watches the companion eat with quiet satisfaction.*"}},
 TAMING={ziel={"Easy, %s. I mean you no harm.","*lowers the weapon and slowly offers %s an open hand.*"},gruppe={"Trust cannot be forced.","*approaches slowly without making a sudden move.*"}},
 TRAP={ziel={"Watch your step, %s. Too late.","*glances toward the carefully hidden trap near %s.*"},gruppe={"Now we only need someone to step into it.","*hides a trap carefully in the terrain.*"}},
 FLARE={ziel={"No more hiding, %s.","*fires a flare toward %s and floods the area with light.*"},gruppe={"Let's see who's hiding there.","*fires a bright flare into the shadows.*"}},
 ASPECT_HAWK={gruppe={"Eyes open. The hawk sees first.","*straightens as the gaze becomes sharp and watchful.*"}}, ASPECT_CHEETAH={gruppe={"Keep up if you can.","*leans forward and breaks into a swift pace.*"}}, ASPECT_MONKEY={gruppe={"Standing still would be unhealthy.","*loosens the stance and begins moving unpredictably.*"}}, RAPID_FIRE={gruppe={"Now don't let up!","*fires shot after shot in rapid succession.*"}}, DISENGAGE={gruppe={"There. Distance restored.","*leaps backward and creates space.*"}}, MELEE={ziel={"Then up close, %s.","*lowers the ranged weapon and draws a melee weapon against %s.*"},gruppe={"Then at arm's length.","*switches to a melee weapon.*"}}, RAPTOR_STRIKE={ziel={"You stepped too close, %s. Poor choice.","*turns the advance of %s into a sharp melee counterstrike.*","A hunter can fight without distance, %s.","*draws a melee weapon and strikes at %s.*"},gruppe={"A good hunter knows when to close the distance.","*draws a melee weapon and sets their feet.*","The hunt does not end when arrows are useless.","*shifts weight forward and swings with practiced precision.*"}}, TRACKING={ziel={"The trail is fresh, %s.","*crouches and studies the tracks left by %s.*"},gruppe={"There. The trail is clear.","*studies ground, branches and wind for fresh signs.*"}}, CAMOUFLAGE={gruppe={"Don't move. Don't stand out. Disappear.","*melts into cover and the surrounding terrain.*"}}, VICTORY={ziel={"The hunt is over, %s.","*lowers the weapon after the final hit and regards %s quietly.*"},gruppe={"The trail ends here.","*checks the surroundings before lowering the weapon.*"}},
    -- Additional WoW Forever hunter actions
    TAME_BEAST = { gruppe = { "Trust is earned, never tied to a leash.", "An open palm does more than a raised weapon.", "*kneels and leaves a respectful distance.*", "*holds still until the animal chooses to approach.*" }, ziel = { "I am not here to break you, %s. I am here to understand." }, },
    CALL_PET = { gruppe = { "Come along, old friend. Work first, supper after.", "One whistle can carry a lifetime of friendship.", "*gives a familiar sharp whistle.*", "*searches the treeline for a well-known silhouette.*" }, },
    DISMISS_PET = { gruppe = { "Rest now, companion. I will keep watch.", "Even a loyal hunter deserves a quiet place.", "*strokes the animal's neck and gives a gentle signal.*", "*waits until the companion is safely out of sight.*" }, ziel = { "Until later, %s. Leave me some of the provisions." }, },
    EAGLE_EYE = { gruppe = { "My eyes can travel farther than my boots.", "First understand the country, then choose the road.", "*shades the eyes and studies the far horizon.*", "*holds an intent gaze on a distant movement.*" }, },
    EYES_OF_THE_BEAST = { gruppe = { "Two sets of eyes, one purpose and much better hearing.", "The world smells different from four paws down.", "*falls silent and concentrates on another pair of senses.*", "*turns toward a sound no human ear could have caught.*" }, ziel = { "Show me what you see, %s." }, },
    SCARE_BEAST = { gruppe = { "Even the longest fangs know the taste of fear.", "One fierce warning may save a longer fight.", "*stands tall and gives a piercing warning cry.*", "*plants both feet and refuses to yield ground.*" }, ziel = { "Back away, %s. Not every prey is easy to bite." }, },
    BEAST_LORE = { gruppe = { "Teeth, coat and gait tell a story worth reading.", "Observation is a craft. Survival is another.", "*studies the beast's posture and the angle of its ears.*", "*quietly notes its tracks and habits.*" }, ziel = { "Magnificent creature, %s. And not without secrets." }, },
    SUMMON_HAWK = { gruppe = { "There is sky enough for two hunters.", "Prey is easier to find when one friend has wings.", "*raises an arm to welcome a circling hawk.*", "*follows a shadow moving high above the treetops.*" }, },
    ASPECT_BEAST = { gruppe = { "Today my footsteps have no reason to be heard.", "To understand the wild, become part of it for a moment.", "*moves with a low, almost soundless gait.*", "*tests the wind and lowers their centre of gravity.*" }, },
    ASPECT_PACK = { gruppe = { "Together we move faster. Together we return.", "A good road feels shorter when every stride agrees.", "*signals for the party to advance in step.*", "*adjusts pace to keep the companions together.*" }, },
    ASPECT_WILD = { gruppe = { "The wind carries more than cold to a careful listener.", "A thicket knows dangers that steel cannot stop.", "*runs fingertips across moss and leaves.*", "*draws in the damp scent of the forest.*" }, },
    TRANQUILIZING_SHOT = { gruppe = { "A furious enemy thinks more clearly when the frenzy ends.", "Sometimes the strongest shot is the one that calms.", "*checks a special round and steadies the ranged weapon.*", "*takes a measured aim meant to end the frenzy.*" }, ziel = { "Enough fury, %s. Time to think again." }, },
    INTIMIDATION = { gruppe = { "My companion is not nearly as impressed by you as you hope.", "A low growl can explain more than a long speech.", "*gives the companion a brief signal to advance.*", "*steps aside to leave a clear path for the beast.*" }, ziel = { "Look into my friend's eyes, %s, and reconsider." }, },
    BESTIAL_WRATH = { gruppe = { "We found each other. Now we fight together.", "Fury cannot be tamed, but it can find a direction.", "*rests a hand against the companion's flank.*", "*releases the beast with a sharp, familiar cry.*" }, ziel = { "Show them the courage inside you, %s!" }, },
    AUTO_SHOT = { gruppe = { "Good marksmanship is built on a steady rhythm.", "Not every shot needs a proclamation; some need silence.", "*draws a fresh bead with an easy practised motion.*", "*keeps breathing even as the weapon follows its mark.*" }, ziel = { "Hold still, %s. It makes my work easier." }, },
    SERPENT_STING = { gruppe = { "A serpent need not bite twice.", "Patience is the sharpest point in this quiver.", "*examines a carefully prepared poisoned point.*", "*slides the treated ammunition into place.*" }, ziel = { "The wilderness has a gift for you, %s. It takes its time." }, },
    CONCUSSIVE_SHOT = { gruppe = { "Haste is no substitute for an escape route.", "A stumbling pursuer seldom catches anything.", "*aims for the line of advance rather than the chest.*", "*fires a quick shot and watches the enemy's footing.*" }, ziel = { "Not so fast, %s. We have matters to settle." }, },
    DISTRACTING_SHOT = { gruppe = { "Over here! If you seek trouble, look at me.", "A battle turns when somebody dares to be seen.", "*steps openly from cover and fires a conspicuous shot.*", "*draws attention with a deliberate movement.*" }, ziel = { "Here I am, %s. Bring your grievances to me." }, },
    SCORPID_STING = { gruppe = { "A scorpion never asks how large its prey is.", "One small sting can steal a giant's strength.", "*selects an unusually fine and prepared point.*", "*watches for the first signs of weakness.*" }, ziel = { "Strength alone will not save you, %s." }, },
    TRUESHOT_AURA = { gruppe = { "Even breaths, clear lines and one shared moment.", "We take separate shots, but stand together.", "*signals the other marksmen and checks their stance.*", "*settles into an exact, balanced shooting posture.*" }, },
    VIPER_STING = { gruppe = { "Some spells dry up before their final word is spoken.", "The viper seeks power, not blood.", "*examines an arrowhead glimmering with pale colour.*", "*watches the enemy caster's hands intently.*" }, ziel = { "Your strength is thinning, %s. Can you feel it?" }, },
    SNIPER_SHOT = { gruppe = { "One breath. One decision. A very long distance.", "The farther the shot, the more closely one must watch.", "*slows the breath and aligns the weapon precisely.*", "*lies utterly still, waiting for the one right moment.*" }, ziel = { "Do not bother looking for me, %s. That moment has passed." }, },
    VOLLEY = { gruppe = { "The sky is about to become a disagreeable place.", "I would advise against standing where the rain will fall.", "*marks a patch of ground and raises the ranged weapon.*", "*sends a succession of projectiles across the battlefield.*" }, },
    SCATTER_SHOT = { gruppe = { "A second of confusion is quite enough.", "Not every shot seeks a wound. Some purchase time.", "*whips the weapon around and fires at close range.*", "*uses a brief opening to change position.*" }, ziel = { "Take a moment to find your bearings, %s!" }, },
    TRACK_BEASTS = { gruppe = { "A fresh trail speaks louder than a hunting horn.", "Claws, fur and churned earth tell the whole story.", "*compares the distance between paw prints.*", "*kneels beside the path and examines a new track.*" }, },
    TRACK_HUMANOIDS = { gruppe = { "Two-legged travellers leave more signs than they know.", "The soles of boots have stories of their own.", "*examines a snapped twig at shoulder height.*", "*reads the uneven rhythm of footprints in the soil.*" }, },
    WING_CLIP = { gruppe = { "Anyone chasing me needs better legs first.", "A well-placed cut can end a reckless pursuit.", "*ducks an attack and sweeps the weapon low.*", "*sidesteps and attempts to cut off the pursuer's path.*" }, ziel = { "Slow down, %s. We are not finished yet." }, },
    IMMOLATION_TRAP = { gruppe = { "An invisible boundary can become very warm indeed.", "Those who assume every path is safe rarely learn twice.", "*conceals a burning trap beneath dirt and pebbles.*", "*checks the trigger and takes a careful step back.*" }, },
    MONGOOSE_BITE = { gruppe = { "A good dodge is half the answer.", "The mongoose waits for the mistake, not the invitation.", "*slips past a strike and makes a quick countercut.*", "*turns one shoulder away and snaps the blade forward.*" }, ziel = { "That momentum belongs to me now, %s." }, },
    TRACK_UNDEAD = { gruppe = { "Some tracks smell of nothing living.", "The dead seldom walk gently through the world.", "*tests the cold earth and the unnaturally quiet patches.*", "*holds their breath and listens for a lifeless shuffle.*" }, },
    FREEZING_TRAP = { gruppe = { "A little stillness can improve any battle.", "Run too hastily and the road may turn to ice.", "*hides a freezing trap beneath a thin layer of earth.*", "*checks that no companion will step on the trigger.*" }, },
    TRACK_HIDDEN = { gruppe = { "Not everything unseen is unheard.", "The wind betrays places where no wind ought to blow.", "*listens for the faintest rustle beyond sight.*", "*studies the shadows for a movement that does not belong.*" }, },
    COUNTERATTACK = { gruppe = { "Thank you for the gap in your defence.", "An attack can be an invitation. I gladly accept.", "*turns aside a blow and returns the weapon at once.*", "*lets the enemy overreach before making a counterthrust.*" }, ziel = { "Your chance has passed, %s. My turn." }, },
    TRACK_ELEMENTALS = { gruppe = { "Where the elements dance, the earth remembers.", "Ash, frost and an odd breeze point the way.", "*touches stone that is warmer than it should be.*", "*follows a trace of frost and crackling air.*" }, },
    FROST_TRAP = { gruppe = { "Not every road leads quickly to its destination.", "One step, a breath of frost and the chase slows down.", "*places the trigger of a cold trap beneath loose leaves.*", "*memorises a safe path around the hidden device.*" }, },
    FEIGN_DEATH = { gruppe = { "Playing dead is a skill. Not laughing is another.", "A wise hunter need not win every fight standing up.", "*drops to the ground with exaggerated finality.*", "*keeps even an eyelid motionless until danger passes.*" }, },
    LACERATE = { gruppe = { "A wound is not a speech, but it is understood.", "Come too close and meet the edge of my steel.", "*makes a hard cut and quickly pulls the weapon back.*", "*drops into a low stance for a short melee strike.*" }, ziel = { "That step was costly, %s." }, },
    TRACK_DEMONS = { gruppe = { "Brimstone and silence seldom make a pleasant combination.", "This trail belongs to no ordinary beast.", "*studies scorched symbols left in the earth.*", "*eyes a track that seems to run against the wind.*" }, },
    EXPLOSIVE_TRAP = { gruppe = { "Fire sometimes answers a question far too loudly.", "This path is about to become shorter. For someone.", "*buries an explosive trigger and checks the safe distance.*", "*steps carefully behind a nearby boulder.*" }, },
    TRACK_GIANTS = { gruppe = { "Large feet make terrible camouflage.", "Where trees are broken, small footprints are unnecessary.", "*rests a hand inside an enormous footprint.*", "*follows a trail of uprooted trees with the eyes.*" }, },
    TRACK_DRAGONKIN = { gruppe = { "Scales, claws, scorch marks. This is no ordinary deer.", "Anyone hunting dragons needs an escape plan first.", "*turns a single enormous scale between the fingers.*", "*carefully follows a burn mark across the stone.*" }, },
    DETERRENCE = { gruppe = { "One step back is not surrender.", "Steel counts for little when survival has no plan.", "*takes a tight, guarded stance.*", "*positions the weapons to deny an easy opening.*" }, },
    STRIDER_KICK = { gruppe = { "You did not see my boot coming from this angle.", "Long legs can deliver a very short answer.", "*throws a sudden low kick while changing direction.*", "*shifts weight and drives a heel forward.*" }, ziel = { "One step too close, %s. Learn some distance." }, },
    BEAST_TRAINING = { gruppe = { "The first lesson begins with trust, not a command.", "A companion learns faster when you listen too.", "*repeats a hand signal patiently and waits.*", "*rewards a successful attempt with a warm nod.*" }, },
}
